#nullable enable // autogenerated

using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2Logic;
using MVZ2Logic.Level;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Grids;
using PVZEngine.Tools;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.errorBlock)]
    public class ErrorBlock : EntityBehaviourDefinition
    {
        public ErrorBlock(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            var level = entity.Level;
            using var tilesItem = level.GetAllGridsDisposeable();
            var tiles = tilesItem.Value;

            using var errorBlocksItem = ListPool<Entity>.Rent();
            var errorBlocks = errorBlocksItem.Value;

            bool full = false;
            foreach (var tile in tiles)
            {
                var errorBlock = GetErrorBlockInTile(tile);
                if (errorBlock != null)
                {
                    full = true;
                    errorBlocks.Add(errorBlock);
                    continue;
                }
                full = false;
                break;
            }
            if (full)
            {
                level.PlaySound(VanillaSoundID.finalItem);
                foreach (var errorBlock in errorBlocks)
                {
                    errorBlock.Remove();
                }
                entity.Remove();
                var pad = entity.Spawn(VanillaContraptionID.antiGravityPad, entity.Position);
                if (pad != null)
                {
                    pad.DestroyConflictGridEntities();
                }
            }
        }
        private static Entity? GetErrorBlockInTile(LawnGrid tile)
        {
            using var errorBlocksInTileItem = ListPool<Entity>.Rent();
            var errorBlocksInTile = errorBlocksInTileItem.Value;

            tile.GetEntities(errorBlocksInTile);

            foreach (var ent in errorBlocksInTile)
            {
                if (ent.ExistsAndAlive() && ent.IsEntityOf(VanillaContraptionID.errorBlock))
                {
                    return ent;
                }
            }
            return null;
        }
    }
}
